# Periodically condense older chat history
def compact_history(history_messages):
 if len(history_messages) > 12:
 condensed_state = summarize_turns(history_messages[:-4])
 return [{'role': 'user', 'content': f'<session_state>{condensed_state}</session_state>'}] + history_messages[-4:]
 return history_messages
